INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1030, '数学', '三年级', 'fill', 3, '{"stem": "填空(7)：妈妈拿了3本书，爸爸拿的书给了妈妈5本后，爸爸现有的书是妈妈现有的书的3倍，爸爸原来拿了（ ）本书。"}', '29', '妈妈现有：3+5=8本；爸爸现有：8×3=24本；爸爸原来：24+5=29本', 'jsj3_sx_v105', '["jsj3_sx","U4","p049","fill_03"]', 1, NULL);
