INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1030, '数学', '三年级', 'single', 2, '{"stem": "选择(3)：下面问题中能用30÷6来列式解决的是（ ）。A. 红花30朵，黄花的朵数是红花的6倍，黄花几朵  B. 红花30朵，比黄花多6朵，黄花几朵  C. 红花30朵，黄花6朵，红花的朵数是黄花的几倍"}', 'C', '30÷6=5，求倍数用除法', 'jsj3_sx_v105', '["jsj3_sx","U4","p050","choice_03"]', 1, NULL);
