INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1030, '数学', '三年级', 'apply', 2, '{"stem": "应用(2)：小军今年8岁了，爷爷的年龄是小军的8倍。(1) 爷爷今年多少岁？(2) 去年爷爷的年龄是小军的多少倍？（10分）"}', '(1) 8×8=64（岁）  (2) 9倍', '(1) 8×8=64岁; (2) 去年爷爷63岁小军7岁，63÷7=9', 'jsj3_sx_v105', '["jsj3_sx","U4","p051","apply_02"]', 1, NULL);
