INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1030, '数学', '三年级', 'apply', 2, '{"stem": "应用(5)：一把椅子315元，一张桌子的价钱是一把椅子的3倍。一张桌子多少元？比一把椅子贵多少元？（8分）"}', '945元, 630元', '315×3=945（元）, 945-315=630（元）', 'jsj3_sx_v105', '["jsj3_sx","U4","p051","apply_05"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1030, '数学', '三年级', 'apply', 3, '{"stem": "思维拓展：白兔比灰兔多32只，已知白兔的只数是灰兔的5倍。白兔、灰兔各有多少只？（10分）"}', '灰兔8只, 白兔40只', '灰兔：32÷(5-1)=8（只）; 白兔：8×5=40（只）', 'jsj3_sx_v105', '["jsj3_sx","U4","p051","think_01"]', 1, NULL);